"use client";

import { useState } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ScrollArea } from "@/components/ui/scroll-area";
import { listOf } from "@/features/chat/lookup";
import {
  formatAverage,
  formatExperience,
  summarizePlayer,
} from "@/features/player/player-schema";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import type { PlayerData, PlayerInfo } from "@/features/player/player-schema";

export type PlayerCardState = "streaming" | "loading" | "ready" | "error";

export interface PlayerCardProperties {
  readonly state: PlayerCardState;
  /**
  The players from the props, shown before the data arrives.
  */
  readonly players?: readonly string[];
  /**
  The players found, one row each, in the order asked.
  */
  readonly data?: readonly PlayerData[];
  /**
  Names that were asked for but not found, noted under the table.
  */
  readonly missing?: readonly string[];
  readonly error?: string;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-[720px]`;

/**
One empty list for every default, so a card without names doesn't get a new array each render.
*/
const NO_NAMES: readonly string[] = [];

const MUTED = "text-muted-foreground";

const STAT = "text-center whitespace-nowrap tabular-nums";

/**
The columns after the photo, number and name, left to right, as on a team's roster page.
*/
const COLUMNS = [
  {
    label: "Ht",
    title: "Height",
    value: (player: PlayerInfo) => player.height ?? "–",
  },
  {
    label: "Age",
    title: "Age",
    value: (player: PlayerInfo) => player.age ?? "–",
  },
  {
    label: "Exp",
    title: "Seasons in the NBA before this one (R for a rookie)",
    value: (player: PlayerInfo) => formatExperience(player.experience),
  },
  {
    label: "PPG",
    title: "Points per game",
    value: (player: PlayerInfo) => formatAverage(player.points),
  },
  {
    label: "APG",
    title: "Assists per game",
    value: (player: PlayerInfo) => formatAverage(player.assists),
  },
  {
    label: "RPG",
    title: "Rebounds per game",
    value: (player: PlayerInfo) => formatAverage(player.rebounds),
  },
  {
    label: "SPG",
    title: "Steals per game",
    value: (player: PlayerInfo) => formatAverage(player.steals),
  },
] as const;

/**
ESPN frames every NBA headshot the same way: 600 by 436, the head centred a little left of the middle, its top about 15% down. Drawn at this size and offset in the 64px circle, a 300px square around the head fills it: head and shoulders rather than mostly jersey.
*/
const HEADSHOT_CROP = { height: 93, left: -31, top: -11, width: 128 };

const ESPN_IMAGES = "https://a.espncdn.com";

/**
The headshot at exactly the size it's drawn, for 1x, 2x and 3x screens, from ESPN's own resizer. Left to shrink the 600px original by itself, the browser takes a fast, soft filter. A photo from anywhere else is used as it is.
*/
function headshotSources(url: string): { src: string; srcSet?: string } {
  if (!url.startsWith(ESPN_IMAGES)) {
    return { src: url };
  }
  const path = url.slice(ESPN_IMAGES.length);
  const sized = (scale: number) => {
    const parameters = new URLSearchParams({
      h: String(HEADSHOT_CROP.height * scale),
      img: path,
      w: String(HEADSHOT_CROP.width * scale),
    });
    return `${ESPN_IMAGES}/combiner/i?${parameters}`;
  };
  return {
    src: sized(1),
    srcSet: `${sized(1)} 1x, ${sized(2)} 2x, ${sized(3)} 3x`,
  };
}

/**
The player's cut-out photo in a circle, cropped to his head and shoulders. An empty circle when ESPN has none or it fails to load.
*/
const Headshot = ({ player }: { readonly player: PlayerInfo }) => {
  const [failed, setFailed] = useState(false);
  const photo = player.headshot ? headshotSources(player.headshot) : null;
  return (
    <span
      aria-hidden
      className="bg-muted relative flex size-16 shrink-0 overflow-hidden rounded-full"
    >
      {!failed && photo ? (
        // eslint-disable-next-line @next/next/no-img-element, react-doctor/nextjs-no-img-element, jsx-a11y/no-noninteractive-element-interactions -- next/image would force the photo host into the installer's next.config; onError drops a broken photo, it is not a user interaction
        <img
          src={photo.src}
          srcSet={photo.srcSet}
          alt=""
          width={HEADSHOT_CROP.width}
          height={HEADSHOT_CROP.height}
          loading="lazy"
          onError={() => setFailed(true)}
          className="absolute max-w-none"
          style={{
            height: HEADSHOT_CROP.height,
            left: HEADSHOT_CROP.left,
            top: HEADSHOT_CROP.top,
            width: HEADSHOT_CROP.width,
          }}
        />
      ) : null}
    </span>
  );
};

const Header = ({
  title,
  season,
}: {
  readonly title: string;
  readonly season?: string;
}) => (
  <header className="flex items-center justify-between gap-3 text-sm">
    <p className="min-w-0 truncate">
      <span className="text-blue-600 dark:text-blue-400">NBA</span>
      <span className={MUTED}> · {title}</span>
    </p>
    {season ? (
      <p className={cn(MUTED, "shrink-0 tabular-nums")}>{season}</p>
    ) : null}
  </header>
);

/**
The team everyone plays for, or null when the players come from more than one: then each row names its own team instead.
*/
function sharedTeam(data: readonly PlayerData[]) {
  const [first] = data;
  return first && data.every((entry) => entry.team.name === first.team.name)
    ? first.team.name
    : null;
}

/**
One row per player under one header row, so every stat lines up in its column for comparing. The rows read in full color: they're there to be compared, so muting them until hovered would only make that harder.
*/
const PlayerTable = ({
  data,
  showTeam,
}: {
  readonly data: readonly PlayerData[];
  readonly showTeam: boolean;
}) => (
  <ScrollArea orientation="horizontal" className="-mx-1">
    <Table className="min-w-[620px] text-sm">
      <caption className="sr-only">
        {listOf(data.map(({ player }) => player.name))}, with per-game averages
        from {data[0]?.statsSeason}
      </caption>
      <TableHeader>
        <TableRow>
          <TableHead scope="col" className="w-0">
            <span className="sr-only">Photo</span>
          </TableHead>
          <TableHead scope="col" className={STAT}>
            #
          </TableHead>
          <TableHead scope="col">Player</TableHead>
          {COLUMNS.map((column) => (
            <TableHead key={column.label} scope="col" className={STAT}>
              <abbr title={column.title} className="no-underline">
                {column.label}
              </abbr>
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {data.map(({ player, team }, index) => (
          <TableRow
            key={player.id}
            index={index}
            className={cn(
              "[&>td]:text-foreground",
              index === data.length - 1 && "border-transparent"
            )}
          >
            <TableCell className="py-1 pr-0">
              <Headshot player={player} />
            </TableCell>
            <TableCell className={STAT}>{player.jersey ?? "–"}</TableCell>
            <TableCell className="whitespace-nowrap">
              <span className="flex flex-col">
                <span>{player.name}</span>
                {showTeam ? (
                  <span className={cn(MUTED, "text-xs")}>{team.name}</span>
                ) : null}
              </span>
            </TableCell>
            {COLUMNS.map((column) => (
              <TableCell key={column.label} className={STAT}>
                {column.value(player)}
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  </ScrollArea>
);

const PlayerError = ({
  players,
  message = "The player service didn't respond. Try again in a moment.",
}: {
  readonly players?: readonly string[];
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {players && players.length > 0
        ? `Couldn't load ${listOf(players)}`
        : "Couldn't load the player"}
    </p>
    <p className={cn(MUTED, "text-xs")}>{message}</p>
  </div>
);

const Bar = ({ className }: { readonly className?: string }) => (
  <div className={cn("bg-muted animate-pulse rounded", className)} />
);

/**
The card while its data is on the way: the same header and a row per player at the table's height, so nothing moves when the players land. Shows the names as soon as they're known.
*/
export const PlayerCardSkeleton = ({
  players = NO_NAMES,
  className,
}: {
  readonly players?: readonly string[];
  readonly className?: string;
}) => {
  const rows = players.length > 0 ? players : [""];
  return (
    <output className={cn(CARD_FRAME, "block", className)}>
      <span className="sr-only">
        {players.length > 0 ? `Loading ${listOf(players)}` : "Loading a player"}
      </span>
      <div aria-hidden className="flex flex-col gap-3">
        <div className="flex h-5 items-center">
          <Bar className="h-3.5 w-44" />
        </div>
        <div className="flex flex-col">
          {/* The header row is 37px (36 on the ladder plus a 1px rule); each player's row is 73px, the 64px photo plus 4px above and below and a 1px rule. */}
          <div className="flex h-[37px] items-center px-3">
            <Bar className="h-3.5 w-12" />
          </div>
          {rows.map((name, index) => (
            <div
              // The names can repeat while the model is still writing them.
              key={`${name}-${index}`}
              className="flex h-[73px] items-center gap-3 px-3"
            >
              <Bar className="size-16 rounded-full" />
              {name ? (
                <p className="text-sm">{name}</p>
              ) : (
                <Bar className="h-3.5 w-36" />
              )}
            </div>
          ))}
        </div>
      </div>
    </output>
  );
};

export default function PlayerCard({
  state,
  players,
  data,
  missing = NO_NAMES,
  error,
  className,
}: PlayerCardProperties) {
  if (state === "ready" && data && data.length > 0) {
    const team = sharedTeam(data);
    return (
      <section
        aria-label={data.map(summarizePlayer).join(" ")}
        className={cn(CARD_FRAME, "flex flex-col gap-3", className)}
      >
        <Header title={team ?? "Players"} season={data[0]?.season} />
        <PlayerTable data={data} showTeam={team === null} />
        {missing.length > 0 ? (
          <p className={cn(MUTED, "text-xs")}>
            Couldn&apos;t find {listOf(missing)}.
          </p>
        ) : null}
      </section>
    );
  }
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <PlayerError players={players} message={error} />
      </div>
    );
  }
  return <PlayerCardSkeleton players={players} className={className} />;
}

"use client";

import { useEffect, useState } from "react";
import PlayerCard from "@/features/player/components/player-card";
import { loadPlayer } from "@/features/player/player-requests";
import { errorMessage, normalizeName } from "@/features/player/player-schema";
import type { PlayerData } from "@/features/player/player-schema";

/**
What came back for one list of players: the ones found, in the order asked, and the names that weren't. A result for a different list reads as still loading, so the card never flashes the wrong players.
*/
type Result =
  | {
      key: string;
      status: "ready";
      data: PlayerData[];
      missing: string[];
    }
  | { key: string; status: "error"; message: string };

/**
The names the model has written so far, trimmed, without blanks or repeats.
*/
function namesOf(players: readonly string[] | undefined) {
  const names = (players ?? []).flatMap((name) => {
    const normalized = normalizeName(name);
    return normalized ? [normalized] : [];
  });
  return [...new Set(names)];
}

export default function LivePlayerCard({
  players: requested,
  streaming = false,
  className,
}: {
  readonly players?: readonly string[];
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  const [result, setResult] = useState<Result | null>(null);
  const names = namesOf(requested);
  const key = names.join("|");

  useEffect(() => {
    let isCancelled = false;
    const run = async (list: readonly string[]) => {
      const settled = await Promise.allSettled(
        list.map((name) => loadPlayer(name))
      );
      const data = settled.flatMap((outcome) =>
        outcome.status === "fulfilled" ? [outcome.value] : []
      );
      const missing = list.filter(
        (_, index) => settled[index]?.status === "rejected"
      );
      const [firstFailure] = settled.flatMap((outcome) =>
        outcome.status === "rejected" ? [outcome.reason] : []
      );
      const next: Result =
        data.length > 0
          ? { data, key, missing, status: "ready" }
          : {
              key,
              message: errorMessage(firstFailure, "Player lookup failed."),
              status: "error",
            };
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming && key) {
      run(key.split("|"));
    }
    return () => {
      isCancelled = true;
    };
  }, [key, streaming]);

  if (streaming || names.length === 0) {
    return (
      <PlayerCard state="streaming" players={names} className={className} />
    );
  }
  const current = result?.key === key ? result : null;
  if (current?.status === "ready") {
    return (
      <PlayerCard
        state="ready"
        data={current.data}
        missing={current.missing}
        className={className}
      />
    );
  }
  if (current?.status === "error") {
    return (
      <PlayerCard
        state="error"
        players={names}
        error={current.message}
        className={className}
      />
    );
  }
  return <PlayerCard state="loading" players={names} className={className} />;
}

import { z } from "zod";

export const playerCatalogEntry = {
  description:
    "NBA players this season, one row each in one table: photo, number, name, height, age and seasons in the league, with points, assists, rebounds and steals per game, and the team each plays for now. It fetches its own data and finds each player's current team itself, so trades and signings are always up to date. Use it whenever the user asks about NBA players: their stats, averages, how they're doing, or what team they're on. Send each player's full name. For a comparison, or several players, put them all in this one card, in the order the user named them, rather than several cards.",
  props: z.object({
    players: z
      .array(z.string())
      .describe(
        'The NBA players\' full names, one or more, e.g. ["LeBron James"] or ["LeBron James", "Victor Wembanyama"].'
      ),
  }),
};

import { listOf } from "@/features/chat/lookup";
import { loadPlayer } from "@/features/player/player-requests";
import { normalizeName } from "@/features/player/player-schema";
import type { CardLookup } from "@/features/chat/lookup";

function playersOf(properties: Record<string, unknown>) {
  const names = Array.isArray(properties.players) ? properties.players : [];
  return names.flatMap((name) => {
    const normalized = typeof name === "string" ? normalizeName(name) : null;
    return normalized ? [normalized] : [];
  });
}

export const playerLookup: CardLookup = {
  intent: (subjects) => `The averages for ${listOf(subjects)}`,
  load: async (properties) => {
    const players = playersOf(properties);
    if (players.length === 0) {
      throw new Error("Name an NBA player.");
    }
    return await Promise.all(players.map((player) => loadPlayer(player)));
  },
  sources: () => [
    {
      href: "https://www.espn.com/nba/players",
      label: "espn.com/nba/players",
    },
  ],
  subject: (properties) => {
    const players = playersOf(properties);
    return players.length > 0 ? listOf(players) : null;
  },
};

import { normalizeName } from "@/features/player/player-schema";
import type { PlayerData } from "@/features/player/player-schema";

const sharedPlayerRequests = new Map<
  string,
  { expiresAt: number; player: Promise<PlayerData> }
>();
/**
A player's averages move at most once a game, so five minutes is fresh enough.
*/
const REUSE_MS = 300_000;

/**
"LeBron James" and " lebron  james" share one request.
*/
function playerKey(name: string) {
  return (normalizeName(name) ?? name).toLowerCase();
}

async function fetchPlayer(name: string) {
  const response = await fetch(
    `/api/player?${new URLSearchParams({ player: name })}`
  );
  const body = (await response.json()) as PlayerData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body ? body.error : `Player request failed: ${response.status}`
    );
  }
  return body;
}

async function requestPlayer(key: string, name: string) {
  try {
    return await fetchPlayer(name);
  } catch (error) {
    sharedPlayerRequests.delete(key);
    throw error;
  }
}

export function loadPlayer(name: string) {
  const key = playerKey(name);
  const hit = sharedPlayerRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.player;
  }
  const player = requestPlayer(key, name);
  sharedPlayerRequests.set(key, { expiresAt: Date.now() + REUSE_MS, player });
  return player;
}

export function primePlayer(name: string, data: PlayerData) {
  sharedPlayerRequests.set(playerKey(name), {
    expiresAt: Infinity,
    player: Promise.resolve(data),
  });
}

import "server-only";
import type {
  PlayerAverages,
  PlayerData,
} from "@/features/player/player-schema";

// Server only: ESPN's site APIs don't allow browser requests (CORS).

const NBA = "https://site.api.espn.com/apis/site/v2/sports/basketball/nba";
const COMMON =
  "https://site.web.api.espn.com/apis/common/v3/sports/basketball/nba";
const SEARCH = "https://site.web.api.espn.com/apis/search/v2";

const TIMEOUT_MS = 8000;
/**
Averages only move after a game, and the answer covers every player in the league, so it's kept for an hour.
*/
const AVERAGES_FRESH_MS = 3_600_000;
const NOT_FOUND = 404;

/**
A lookup that found no player, or one who isn't on a team.
*/
export class PlayerNotFoundError extends Error {
  readonly status = NOT_FOUND;

  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "PlayerNotFoundError";
  }
}

interface EspnRoster {
  season?: { displayName?: string };
  team?: { abbreviation: string; displayName: string };
  athletes?: {
    id: string;
    displayName: string;
    jersey?: string;
    displayHeight?: string;
    age?: number;
    experience?: { years?: number };
    headshot?: { href?: string };
  }[];
}

interface EspnAverages {
  requestedSeason?: { displayName?: string };
  categories?: { name: string; names: string[] }[];
  athletes?: {
    athlete: { id: string };
    categories: { name: string; values: number[] }[];
  }[];
}

interface EspnSearch {
  results?: {
    type: string;
    contents?: { uid?: string; defaultLeagueSlug?: string }[];
  }[];
}

async function espn<T>(url: string): Promise<T> {
  const response = await fetch(url, {
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new Error(`The player service returned ${response.status}.`);
  }
  return (await response.json()) as T;
}

const averagesCache: {
  current: { expiresAt: number; value: Promise<EspnAverages> } | null;
} = { current: null };

async function fetchAverages() {
  try {
    // Without a season, ESPN answers with the latest one that has games, and says which.
    return await espn<EspnAverages>(
      `${COMMON}/statistics/byathlete?seasontype=2&limit=1000`
    );
  } catch (error) {
    averagesCache.current = null;
    throw error;
  }
}

/**
Every player's averages in one answer, kept for an hour and forgotten if the request fails.
*/
function leagueAverages() {
  const hit = averagesCache.current;
  if (hit && Date.now() < hit.expiresAt) {
    return hit.value;
  }
  const value = fetchAverages();
  averagesCache.current = { expiresAt: Date.now() + AVERAGES_FRESH_MS, value };
  return value;
}

/**
The NBA player ESPN's search finds first for a name, and the team he plays for now.
*/
async function findPlayer(query: string) {
  const parameters = new URLSearchParams({
    limit: "5",
    query,
    type: "player",
  });
  const body = await espn<EspnSearch>(`${SEARCH}?${parameters}`);
  const match = body.results
    ?.find((result) => result.type === "player")
    ?.contents?.find((content) => content.defaultLeagueSlug === "nba");
  // A player's uid ends in his id: "s:40~l:46~a:1966".
  const playerId = match?.uid?.split("~a:", 2)[1];
  if (!playerId) {
    throw new PlayerNotFoundError(`No NBA player called "${query}".`);
  }
  const { athlete } = await espn<{
    athlete: { displayName: string; team?: { id: string } };
  }>(`${COMMON}/athletes/${playerId}`);
  if (!athlete.team) {
    throw new PlayerNotFoundError(
      `${athlete.displayName} isn't on an NBA team right now.`
    );
  }
  return { playerId, teamId: athlete.team.id };
}

const NO_AVERAGES: PlayerAverages = {
  assists: null,
  points: null,
  rebounds: null,
  steals: null,
};

/**
One player's per-game points, assists, rebounds and steals. ESPN files each stat under a category with a parallel list of names, so they're found by name rather than by position.
*/
function averagesOf(body: EspnAverages, playerId: string): PlayerAverages {
  const entry = body.athletes?.find(({ athlete }) => athlete.id === playerId);
  if (!entry) {
    return NO_AVERAGES;
  }
  const categoryList = body.categories ?? [];
  const read = (name: string) => {
    for (const category of categoryList) {
      const index = category.names.indexOf(name);
      if (index !== -1) {
        const value = entry.categories.find(
          (candidate) => candidate.name === category.name
        )?.values[index];
        return typeof value === "number" ? value : null;
      }
    }
    return null;
  };
  return {
    assists: read("avgAssists"),
    points: read("avgPoints"),
    rebounds: read("avgRebounds"),
    steals: read("avgSteals"),
  };
}

/**
Seasons played before this one, as a roster page counts them. ESPN counts the current season for everyone but this year's rookies, who get 0: a second-year player reads 2, LeBron James in his 24th season reads 24.
*/
function seasonsBefore(years = 0) {
  return Math.max(years - 1, 0);
}

/**
One NBA player this season: his team now, his number, height, age and experience from its roster, and his per-game averages.
*/
export async function getPlayer(name: string): Promise<PlayerData> {
  const { playerId, teamId } = await findPlayer(name);
  const [roster, averages] = await Promise.all([
    espn<EspnRoster>(`${NBA}/teams/${teamId}/roster`),
    leagueAverages(),
  ]);
  const athlete = roster.athletes?.find(
    (candidate) => candidate.id === playerId
  );
  if (!athlete) {
    throw new PlayerNotFoundError(
      `Couldn't find "${name}" on the ${roster.team?.displayName ?? "team's"} roster.`
    );
  }
  return {
    asOf: Date.now(),
    player: {
      age: athlete.age ?? null,
      experience: seasonsBefore(athlete.experience?.years),
      headshot: athlete.headshot?.href ?? null,
      height: athlete.displayHeight ?? null,
      id: athlete.id,
      jersey: athlete.jersey ?? null,
      name: athlete.displayName,
      ...averagesOf(averages, athlete.id),
    },
    season: roster.season?.displayName ?? "",
    statsSeason: averages.requestedSeason?.displayName ?? "",
    team: {
      abbreviation: roster.team?.abbreviation ?? "",
      name: roster.team?.displayName ?? "",
    },
  };
}

/**
Per-game averages for the stats season. Each is null when the player didn't play in it.
*/
export interface PlayerAverages {
  points: number | null;
  assists: number | null;
  rebounds: number | null;
  steals: number | null;
}

/**
One player: who he is, and how he's averaging.
*/
export interface PlayerInfo extends PlayerAverages {
  /**
  ESPN's id for the player.
  */
  id: string;
  /**
  e.g. "LeBron James".
  */
  name: string;
  /**
  The jersey number as a string, so "00" keeps both zeros. Null before one is assigned.
  */
  jersey: string | null;
  /**
  e.g. "6' 9\"".
  */
  height: string | null;
  age: number | null;
  /**
  Seasons in the NBA before this one; 0 for a rookie.
  */
  experience: number;
  /**
  A cut-out photo, a PNG. Null when ESPN has none.
  */
  headshot: string | null;
}

/**
One NBA player this season.
*/
export interface PlayerData {
  player: PlayerInfo;
  /**
  The team he plays for now.
  */
  team: {
    /**
    e.g. "Philadelphia 76ers".
    */
    name: string;
    abbreviation: string;
  };
  /**
  This season, e.g. "2026-27".
  */
  season: string;
  /**
  The season the averages come from: this one once it has games, the one before until then.
  */
  statsSeason: string;
  /**
  Unix time in milliseconds the player was read.
  */
  asOf: number;
}

/**
"lebron  james " reads "lebron james". Null when nothing is left.
*/
export function normalizeName(name: string | null = ""): string | null {
  const trimmed = (name ?? "").trim().replaceAll(/\s+/gu, " ");
  return trimmed || null;
}

/**
The message of a thrown error, or the fallback when something else was thrown. Uses instanceof rather than Error.isError, which Node 22 and older browsers don't have.
*/
export function errorMessage(error: unknown, fallback: string): string {
  // eslint-disable-next-line unicorn/prefer-error-is-error -- Error.isError is missing on Node 22 and older browsers
  return error instanceof Error ? error.message : fallback;
}

/**
"R" for a rookie, else the seasons played, as a roster page writes it.
*/
export function formatExperience(years: number): string {
  return years === 0 ? "R" : String(years);
}

/**
An average to one decimal, or a dash when there is none.
*/
export function formatAverage(value: number | null): string {
  return value === null ? "–" : value.toFixed(1);
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizePlayer(data: PlayerData): string {
  const { player } = data;
  const who = `${player.name}, ${data.team.name}`;
  return player.points === null
    ? `${who}: no averages from ${data.statsSeason} yet.`
    : `${who}: ${formatAverage(player.points)} points, ${formatAverage(player.assists)} assists, ${formatAverage(player.rebounds)} rebounds and ${formatAverage(player.steals)} steals a game in ${data.statsSeason}.`;
}

/**
The surface every data card shares: the page's own background and text, and one hairline border. Cards with their own shape (a seat map, a ticket stub) take just this.
*/
export const CARD_SURFACE = "bg-background text-foreground border";

/**
The whole frame of a plain data card: the shared surface with 1rem corners and 1rem of padding. Each card adds its own width.
*/
export const CARD_FRAME = `${CARD_SURFACE} rounded-2xl p-4`;

import {
  getPlayer,
  PlayerNotFoundError,
} from "@/features/player/player-queries";
import { errorMessage, normalizeName } from "@/features/player/player-schema";

const CACHE = "public, s-maxage=300, stale-while-revalidate=3600";

const UPSTREAM_FAILED = 502;

function statusOf(error: unknown) {
  return error instanceof PlayerNotFoundError ? error.status : UPSTREAM_FAILED;
}

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const player = normalizeName(searchParams.get("player"));
  if (!player) {
    return Response.json(
      { error: 'Pass an NBA player such as "LeBron James".' },
      { status: 400 }
    );
  }

  try {
    return Response.json(await getPlayer(player), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    return Response.json(
      { error: errorMessage(error, "Player lookup failed.") },
      { status: statusOf(error) }
    );
  }
}
